import React, { useEffect, useState } from 'react';
import Question from './Question';
import Results from './Results';

/*const questions = [
    {
        question: "Какое из этих предприятий производит тракторы?",
        answers: [
            { text: "МТЗ", correct: true },
            { text: "БелАЗ", correct: false },
            { text: "Гродненский мясокомбинат", correct: false },
            { text: "Кристалл", correct: false },
        ],
    },
    {
        question: "Где расположен завод 'Гомсельмаш'?",
        answers: [
            { text: "Гомель", correct: true },
            { text: "Минск", correct: false },
            { text: "Брест", correct: false },
            { text: "Витебск", correct: false },
        ],
    },
    // Добавьте больше вопросов по желанию
];*/

function Quiz() {
    const [questions, setQuestions] = useState([]);
    const [currentQuestion, setCurrentQuestion] = useState(0);
    const [score, setScore] = useState(0);
    const [finished, setFinished] = useState(false);

    useEffect(() => {
        const fetchQuestion = async () => {
            const response = await fetch("http://localhost:4000/questions");
            const data = await response.json();
            setQuestions(data);
        }
    })

    const handleAnswer = (isCorrect) => {
        if (isCorrect) {
            setScore(score + 1);
        }
        const nextQuestion = currentQuestion + 1;
        if (nextQuestion < questions.length) {
            setCurrentQuestion(nextQuestion);
        } else {
            setFinished(true);
        }
    };

    if (finished) {
        return <Results score={score} total={questions.length} />;
    }

    if (questions.length === 0) {
        return <div>Загрузка...</div>
    }

    return (
        <div>
            <h2>Тест: Предприятия Беларуси</h2>
            <Question
                question={questions[currentQuestion].question}
                answers={questions[currentQuestion].answers}
                onAnswer={handleAnswer}
            />
        </div>
    );
}

export default Quiz;
